  let moshBlock = floor(uv * res / 16.0);
  if (glitchHash(vec3f(moshBlock, floor(frameU.absTime * 4.0))) < params.mosh) {
    let motion = cameraMotion((moshBlock + 0.5) * 16.0 / res);
    color = previousAt(uv - motion * 1.5);
  }
  return vec4f(color, 1.0);
